});

function convert_notice_period_inline(frm) {
    let field = frm.get_field('notice_period_acceptable');

    if (field && field.$wrapper) {
        // Hide all select-related elements
        field.$wrapper.find('select, .control-input, .control-input-wrapper').hide();

        // Remove existing custom elements
        field.$wrapper.find('.custom-radio-inline').remove();

        // Get the original label
        let label_text = field.$wrapper.find('.control-label').text().trim();

        // Create inline radio layout
        let inline_html = `
            <div class="custom-radio-inline">
                <div class="form-group" style="margin-bottom: 15px;">
                    <div style="display: flex; justify-content: space-between; align-items: center; min-height: 36px;">
                        <label class="control-label" style="margin: 0; font-weight: 500; color: #555;">
                            ${label_text}
                        </label>
                        <div class="radio-buttons-right" style="display: flex; gap: 20px;">
                            <label class="radio-option-inline" style="cursor: pointer; display: flex; align-items: center; margin: 0; font-weight: normal;">
                                <input type="radio" name="notice_period_inline" value="Yes" 
                                       ${frm.doc.notice_period === 'YES' ? 'checked' : ''} 
                                       style="margin-right: 8px; transform: scale(1.3);">
                                <span style="font-weight: 600; font-size: 14px;">YES</span>
                            </label>
                            <label class="radio-option-inline" style="cursor: pointer; display: flex; align-items: center; margin: 0; font-weight: normal;">
                                <input type="radio" name="notice_period_inline" value="No" 
                                       ${frm.doc.notice_period === 'NO' ? 'checked' : ''} 
                                       style="margin-right: 8px; transform: scale(1.3);">
                                <span style="font-weight: 600; font-size: 14px;">NO</span>
                            </label>
                        </div>
                    </div>
                </div>
            </div>
        `;

        // Hide original label and replace with custom layout
        field.$wrapper.find('.control-label').hide();
        field.$wrapper.prepend(inline_html);

        // Handle radio changes
        field.$wrapper.find('input[name="notice_period_inline"]').change(function() {
            let value = $(this).val();
            frm.set_value('notice_period_acceptable', value);
        });

        // Add styling
        add_inline_radio_styles();
    }
}

function add_inline_radio_styles() {
    if (!$('#inline-radio-styles').length) {
        $('head').append(`
            <style id="inline-radio-styles">
                .custom-radio-inline {
                    width: 100%;
                }

                .custom-radio-inline .form-group {
                    // border-bottom: 1px solid #d1d8dd;
                    padding: 8px 0;
                }

                .radio-option-inline:hover {
                    opacity: 0.8;
                    transition: opacity 0.2s;
                }

                .radio-option-inline input[type="radio"] {
                    accent-color: #007bff;
                }

                /* Ensure no dropdown elements show */
                .custom-radio-inline ~ .control-input,
                .custom-radio-inline ~ .control-input-wrapper {
                    display: none !important;
                }
            </style>
        `);
    }
}

