frappe.listview_settings["Candidate Assessment"] = {
    onload(listview) {
        listview.page.add_button(__('Create Interview'), () => {
            let selected = listview.get_checked_items();

            if (!selected.length) {
                frappe.msgprint(__('Please select at least one record.'));
                return;
            }

            // Har ek Candidate Assessment ke liye Interview record banao
            selected.forEach(row => {
                frappe.call({
                    method: "frappe.client.insert",
                    args: {
                        doc: {
                            doctype: "Interview",
                            candidate_assessment: row.name,   // link field
                            interview_date: frappe.datetime.now_datetime()
                        }
                    },
                    callback: function(r) {
                        if (!r.exc) {
                            frappe.show_alert({
                                message: __('Interview created for ' + row.name),
                                indicator: 'green'
                            });
                        }
                    }
                });
            });
        });
    }
};

