    onload(listview) {
        listview.page.add_button(__('Create Interview'), () => {
            let selected = listview.get_checked_items();
            if (!selected.length) {
                frappe.msgprint(__('Please select at least one record.'));
                return;
            }

            // Filter only passed candidates
         

            

            // Show confirmation dialog
            frappe.confirm(
                __('Create interviews for {0} passed candidate(s)?', [selected.length]),
                () => {
                    // Create Interview records for passed candidates only
                  selected.forEach(row => {
                frappe.call({
                    method: "frappe.client.insert",
                    args: {
                        doc: {
                            doctype: "Interview",
                            candidate_assessment: row.name,   // link field
                                                        candidate:row.candidate,

                            interview_date: frappe.datetime.now_datetime()
                        }
